type Tab='inicio'|'clientes'|'orcamentos'|'agenda'|'vacinas'|'menu'
const money=(v:number)=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const dateKey=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const localDate=()=>dateKey(new Date())
const dateBR=(v:string)=>{const [year,month,day]=v.split('-');return year&&month&&day?`${day}/${month}/${year}`:v}
const dateLongBR=(v:string)=>{const [year,month,day]=v.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date(year,month-1,day))}
const parseDateParts=(value:string)=>{
 const clean=value.trim()
 if(/^\d{4}-\d{2}-\d{2}$/.test(clean)){const [year,month,day]=clean.split('-').map(Number);return {year,month,day}}
 if(/^\d{2}\/\d{2}\/\d{4}$/.test(clean)){const [day,month,year]=clean.split('/').map(Number);return {year,month,day}}
 return null
}
const dateToUtc=(value:string)=>{const parts=parseDateParts(value);return parts?Date.UTC(parts.year,parts.month-1,parts.day):Number.NaN}
const daysBetween=(entry:string,exit:string)=>{
 if(!entry||!exit)return 1
 const start=dateToUtc(entry),end=dateToUtc(exit),difference=(end-start)/86400000
 return Number.isFinite(difference)&&difference>=1?Math.round(difference):1
}
const budgetDays=(b:Pick<Budget,'entryDate'|'exitDate'|'days'> & {manualDays?:boolean})=>b.manualDays?Math.max(1,Math.round(b.days||1)):daysBetween(b.entryDate,b.exitDate)
const totalBudget=(b:Budget)=>{if(typeof b.discountedTotal==='number')return Math.max(0,b.discountedTotal);const days=budgetDays(b);return Math.max(0,b.dailyRate*days+(b.timeExtra?(b.timeExtraValue??30):0)+(b.seasonType==='Nenhum'?0:(b.seasonMode==='%'?b.dailyRate*days*b.seasonValue/100:b.seasonValue))-b.discount+(b.services||[]).reduce((sum,x)=>sum+x.value*x.quantity,0))}
// Converte valores digitados no padrão brasileiro: "1.234,56", "R$ 80,00", "150", "150.5".
// Retorna NaN quando o texto não é um valor válido.
const parseMoney=(text:string)=>{let s=text.replace(/R\$|\s/g,'');if(!s)return Number.NaN;if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');return /^\d+(\.\d+)?$/.test(s)?Number(s):Number.NaN}
const phoneMask=(v:string)=>{const d=v.replace(/\D/g,'').slice(0,11);if(d.length<=2)return d?`(${d}`:'';if(d.length<=6)return `(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length<=10)return `(${d.slice(0,2)}) ${d.slice(2,6)}-${d.slice(6)}`;return `(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7)}`}

export default function App(){
 const [data,setData]=useState<AppData>(loadData),[tab,setTab]=useState<Tab>('inicio'),[loading,setLoading]=useState(true),[intent,setIntent]=useState<'pet'|'budget'|null>(null)
 useEffect(()=>{const t=setTimeout(()=>setLoading(false),900);return()=>clearTimeout(t)},[]);const saveWarned=useRef(false);useEffect(()=>{if(saveData(data)){saveWarned.current=false;return}if(!saveWarned.current){saveWarned.current=true;alert('Atenção: não foi possível salvar as últimas alterações porque o armazenamento do aparelho está cheio. Faça um backup em Menu › Financeiro e remova fotos ou anexos grandes.')}},[data])
 const go=(t:Tab,i:null|'pet'|'budget'=null)=>{setIntent(i);setTab(t)}
 if(loading)return <div className="splash"><div className="splashLogo"><img src="/logo.jpeg"/><span>♥</span></div><h1>Colônia de Férias da Tia Cí</h1><p>Preparando o cantinho dos Aumigos…</p></div>
 return <div className="app"><header className="topbar"><div className="brandMark"><img src="/logo.jpeg"/></div><div className="brandName"><strong>Colônia de Férias da Tia Cí</strong><span><Sparkles/> Cuidado, carinho e diversão</span></div><div className="headerPaw"><PawPrint/></div></header><main>
  {tab==='inicio'&&<Dashboard data={data} go={go}/>} {tab==='clientes'&&<Clients data={data} setData={setData} openIntent={intent==='pet'} clearIntent={()=>setIntent(null)}/>} {tab==='orcamentos'&&<Budgets data={data} setData={setData} openIntent={intent==='budget'} clearIntent={()=>setIntent(null)}/>} {tab==='agenda'&&<Agenda data={data}/>} {tab==='vacinas'&&<Vaccines data={data} setData={setData}/>} {tab==='menu'&&<Menu data={data} setData={setData}/>} 
 </main><nav>{([['inicio',Home,'Início'],['clientes',Users,'Hóspedes'],['orcamentos',CircleDollarSign,'Orçamento'],['agenda',CalendarDays,'Agenda'],['vacinas',Syringe,'Vacinas'],['menu',PawPrint,'Menu']] as const).map(([id,I,label])=><button key={id} className={tab===id?'active':''} onClick={()=>go(id)}><I/><span>{label}</span></button>)}</nav></div>
}

function Dashboard({data,go}:{data:AppData,go:(t:Tab,i?:null|'pet'|'budget')=>void}){
 const [now,setNow]=useState(new Date()),[showGuests,setShowGuests]=useState(false)
 useEffect(()=>{const t=setInterval(()=>setNow(new Date()),1000);return()=>clearInterval(t)},[])
 const today=localDate()
 const valid=data.budgets.filter(b=>!['Cancelado','Rascunho'].includes(b.status))
 const active=valid.filter(b=>b.status==='Entrada confirmada'&&b.entryDate<=today&&b.exitDate>=today)
 const entries=valid.filter(b=>b.entryDate===today)
 const exits=valid.filter(b=>b.exitDate===today)
 const hour=now.getHours(),greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite'
 const received=(b:Budget)=>(b.payments||[]).reduce((sum,p)=>sum+p.value,0)||(b.paidValue||0)
 const guestCard=(b:Budget,kind:'entry'|'exit'|'active')=>{const pet=data.pets.find(p=>p.id===b.petId),total=totalBudget(b),paid=received(b),balance=Math.max(0,total-paid),status=balance<=0?'Pago':paid>0?'Parcial':'Pendente';return <article className="hotelGuestCard" key={`${kind}-${b.id}`}><Avatar pet={pet}/><div className="hotelGuestInfo"><b>{pet?.name||'Hóspede removido'}</b><span>{kind==='entry'?`Entrada: ${dateBR(b.entryDate)}`:kind==='exit'?`Saída: ${dateBR(b.exitDate)}`:`Saída prevista: ${dateBR(b.exitDate)}`}</span><strong>{money(total)}</strong></div><em className={`paymentTag ${status.toLowerCase()}`}>{status}</em></article>}
 return <section className="dashboardHome"><div className="welcome"><div><h1>{greeting}, Tia Cí! <PawPrint/></h1><p>{entries.length||exits.length?`Hoje: ${entries.length} entrada(s) e ${exits.length} saída(s).`:'Tudo organizado para os hóspedes de hoje.'}</p></div><div className="datetime"><Clock3/><div><b>{now.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',hour12:false})}</b><span>{now.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</span></div></div></div>
 <button className="hotelOverviewCard" onClick={()=>setShowGuests(true)}><div className="hotelOverviewTop"><div className="hotelIcon"><HousePlus/></div><div><span>Hóspedes no Hotel</span><b>{active.length} Hospedados</b></div><ChevronRight/></div><div className="hotelOverviewStats"><span><i className="dot in"/>Entradas hoje <b>{entries.length}</b></span><span><i className="dot out"/>Saídas hoje <b>{exits.length}</b></span></div></button>
 <div className="quick dashboardQuick"><button onClick={()=>go('clientes','pet')}><Users/><b>+ Novo Hóspede</b></button><button onClick={()=>go('orcamentos','budget')}><CircleDollarSign/><b>+ Novo Orçamento</b></button><button onClick={()=>go('agenda')}><CalendarDays/><b>Abrir Agenda</b></button></div>
 {showGuests&&<Modal close={()=>setShowGuests(false)} title="Movimentação do Hotel"><div className="hotelSections"><section><h3><i className="dot in"/>Entradas hoje</h3>{entries.length?entries.map(b=>guestCard(b,'entry')):<Empty text="Nenhuma entrada prevista para hoje."/>}</section><section><h3><i className="dot out"/>Saídas hoje</h3>{exits.length?exits.map(b=>guestCard(b,'exit')):<Empty text="Nenhuma saída prevista para hoje."/>}</section><section><h3><PawPrint/>Hóspedes no Hotel</h3>{active.length?active.map(b=>guestCard(b,'active')):<Empty text="Nenhum hóspede no hotel agora."/>}</section></div></Modal>}</section>
}
type PetForm={name:string;species:PetSpecies;breed:string;birthDate:string;age:string;sex:'Macho'|'Fêmea'|'';neutered:'Sim'|'Não'|'';temperament:string[];temperamentNotes:string;medicationType:'Contínua'|'Pontual'|'';medicationDetails:string;postStayNotes:string;guardian:string;phone:string;address:string;guardianRg:string;guardianCpf:string;guardianInstagram:string;emergencyName:string;emergencyRelation:string;emergencyPhone:string;vetClinic:string;vetClinicPhone:string;veterinarianName:string;veterinarianPhone:string;notes:string;photo:string;latitude?:number;longitude?:number;term:PetTerm}
const emptyTerm:PetTerm={vaccinesUpToDate:'',dewormingUpToDate:'',fleaTickMedication:'',imageAuthorization:'',bathOnExit:'',belongings:[],otherBelongings:'',foodQuantity:'',mealsPerDay:'',feedingTimes:'',instructions:''}
const blankPet:PetForm={name:'',species:'Cão',breed:'',birthDate:'',age:'',sex:'',neutered:'',temperament:[],temperamentNotes:'',medicationType:'',medicationDetails:'',postStayNotes:'',guardian:'',phone:'',address:'',guardianRg:'',guardianCpf:'',guardianInstagram:'',emergencyName:'',emergencyRelation:'',emergencyPhone:'',vetClinic:'',vetClinicPhone:'',veterinarianName:'',veterinarianPhone:'',notes:'',photo:'',term:emptyTerm}
const temperamentOptions=['Dócil','Separar na alimentação','Late sem parar','Demonstrou agressividade','Destrói objetos','Faz xixi em tudo','Ciumento']
const dogBreeds=['Sem raça definida (SRD)','Affenpinscher','Afghan Hound','Airedale Terrier','Akita','Alaskan Malamute','American Bully','American Staffordshire Terrier','Australian Cattle Dog','Australian Shepherd','Basenji','Basset Hound','Beagle','Bearded Collie','Bernese Mountain Dog','Bichon Frisé','Bloodhound','Border Collie','Borzoi','Boston Terrier','Boxer','Bull Terrier','Bulldog Francês','Bulldog Inglês','Bullmastiff','Cane Corso','Cavalier King Charles Spaniel','Chihuahua','Chow Chow','Cocker Spaniel Americano','Cocker Spaniel Inglês','Collie','Dachshund','Dálmata','Dobermann','Dogo Argentino','Dogue Alemão','Dogue de Bordeaux','Fila Brasileiro','Fox Paulistinha','Fox Terrier','Galgo Inglês','Golden Retriever','Greyhound','Husky Siberiano','Jack Russell Terrier','Labrador Retriever','Lhasa Apso','Maltês','Mastiff Inglês','Mastim Napolitano','Old English Sheepdog','Papillon','Pastor Alemão','Pastor Australiano','Pastor Belga Groenendael','Pastor Belga Malinois','Pastor de Shetland','Pequinês','Pinscher','Pit Bull','Pointer Inglês','Poodle','Pug','Rottweiler','Samoieda','São Bernardo','Schnauzer Gigante','Schnauzer Miniatura','Schnauzer Standard','Scottish Terrier','Shar-pei','Shiba Inu','Shih-tzu','Spitz Alemão','Staffordshire Bull Terrier','Weimaraner','West Highland White Terrier','Whippet','Yorkshire Terrier','Outra']
