 {cancelBudget&&<Modal close={()=>setCancelBudget(null)} title="Cancelar orçamento"><div className="deleteWarning"><X/><h3>Tem certeza que deseja cancelar o orçamento de {nameOf(cancelBudget)}?</h3><p>O orçamento sairá dos ativos, mas continuará no histórico do pet.</p></div><div className="actions"><button onClick={()=>setCancelBudget(null)}>Voltar</button><button className="confirmDelete" onClick={confirmCancel}>Sim, cancelar</button></div></Modal>}
